<section class="page-hero"><div class="container"><h1><?=text('search')?></h1><p class="lead"><?=$q?'“'.e($q).'”':text('search_intro')?></p></div></section><main class="section-padding"><div class="container"><form action="<?=e(cms_url('/search/'))?>" class="d-flex gap-2 mb-5"><input class="form-control" type="search" name="q" value="<?=e($q)?>" placeholder="<?=text('search')?>" aria-label="<?=text('search')?>"><button class="btn-submit px-4"><?=text('search')?></button></form><?php foreach($results as $result):?><article class="mb-4"><h2 class="h4"><a href="<?=e(cms_url(App\Services\Navigation::recordUrl($result['module'],$result)))?>"><?=e($result['title'])?></a></h2><p><?=e(mb_strimwidth(strip_tags($result['description']??''),0,240,'…'))?></p></article><?php endforeach?><?php if($q&&!$results):?><p><?=text('search_empty')?></p><?php endif?><?php cms_view('public/pagination',compact('total','number','perPage'));?></div></main>
